inputs = ['idh', 'ebc', 'dzgi', 'wuccdd', 'ivuwyx']
outputs = ['idfdyh', 'ebc', 'dvyzyzgi', 'wicdd', 'ivyzuwyx']

# Let's look at what actually changes
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    if inp != out:
        print(f"Example {i}: '{inp}' -> '{out}'")
        # Show character positions that differ
        min_len = min(len(inp), len(out))
        for j in range(min_len):
            if inp[j] != out[j]:
                print(f"  Position {j}: '{inp[j]}' -> '{out[j]}'")
        if len(inp) != len(out):
            print(f"  Length change: {len(inp)} -> {len(out)}")
    else:
        print(f"Example {i}: '{inp}' -> '{out}' (no change)")
    print()

